// Replace pre with cards
'use client';
import {useEffect,useState} from 'react';
export default function Status(){ const [d,setD]=useState<any>(); useEffect(()=>{(async()=>{ const r=await fetch('/statuspage',{cache:'no-store'}); setD(await r.json()); })();},[]);
if(!d) return <div className='max-w-3xl mx-auto py-8'>Loading…</div>;
return (<div className='max-w-3xl mx-auto py-8'>
  <h1 className='text-xl font-bold'>VitalCV — Status</h1>
  <div className='grid gap-3 mt-4'>
    <div className={'p-3 border rounded '+(d.health?.ok?'bg-green-50':'bg-red-50')}><b>API Health</b><div className='text-xs opacity-80'>{String(d.health?.ok)}</div></div>
    <div className={'p-3 border rounded '+(d.jwks?'bg-green-50':'bg-red-50')}><b>Keys (JWKS)</b><div className='text-xs opacity-80'>{String(d.jwks)}</div></div>
    <div className={'p-3 border rounded '+(d.metrics?'bg-green-50':'bg-red-50')}><b>Metrics</b><div className='text-xs opacity-80'>{String(d.metrics)}</div></div>
  </div>
</div>);}
